export const TEST_REPORT_GENERATED_MARKER = '<!-- maison:generated:test-report v1 -->';

export interface TestReportWriterInput {
  projectRoot: string;
  feature: string;
  /** testing 阶段 reports 目录（device-test-*.meta.json / device-test-timing.json 所在） */
  reportsDir: string;
  /** 权威 run 的 hylyre/trace.json；null = 无本轮 trace（报告仍生成，功能轴 UNKNOWN） */
  tracePath: string | null;
  /** 顶层 test-plan.md 全文 */
  planMd: string;
  channelDecl: ExecutionChannelDeclarationResult;
  /** visual/channel/P0 共用的逐 TC 机器裁决；不在 writer 内重算。 */
  channelEvidenceBindings?: readonly ChannelEvidenceBinding[];
  /** testing gate 本轮视觉检查结果集合（visual_diff* 与 visual_reference_viewport）；其中任一真实阻断时总体结论 FAILED（能力缺席投影除外，只进缺口）。缺省 = 调用方未提供。 */
  visualChecks?: ReadonlyArray<DispositionCheck & { blocking_class?: string; failure_kind?: string }>;
  now?: () => Date;
}

export type AxisStatus = 'PASS' | 'FAIL' | 'UNKNOWN' | 'NOT_APPLICABLE';
export type CheckStatus = 'CHECKED' | 'UNKNOWN' | 'NOT_APPLICABLE';
export type OverallStatus = 'COMPLETE' | 'COMPLETE_WITH_GAPS' | 'FAILED';

export interface TestReportConclusion {
  functional: AxisStatus;
  stability: AxisStatus;
  visual_geometry: AxisStatus;
  visual_content: CheckStatus;
  visual_style: CheckStatus;
  gaps: string[];
  overall: OverallStatus;
  /** 报告声明行（达标 / 有条件达标 / 不达标） */
  declared_verdict: '达标' | '有条件达标' | '不达标';
}

export interface GeneratedTestReport {
  content: string;
  conclusion: TestReportConclusion;
  trace_path: string | null;
}

interface PlanRow {
  id: string;
  name: string;
  priority: string;
  channelRaw: string;
  acRefs: string[];
}

type RowStatus = '通过' | '失败' | '阻塞' | '跳过';

interface ExecRow {
  id: string;
  name: string;
  priority: string;
  status: RowStatus;
  duration: string;
  note: string;
  /** 参与"通过率"分子的执行事实来源；capability = visual 绑定因视觉能力缺席未验证（留分母、不算通过也不算失败） */
  source: 'hylyre' | 'visual' | 'gap' | 'invalid' | 'absent' | 'capability';
}

interface DefectRow {
  id: string;
  cases: string;
  severity: 'BLOCKER' | 'MAJOR' | 'MINOR';
  description: string;
  status: string;
}

function readJson<T>(p: string): T | null {
  try {
    if (!fs.existsSync(p)) return null;
    return JSON.parse(fs.readFileSync(p, 'utf-8')) as T;
  } catch {
    return null;
  }
}

function sha256File(p: string): string | null {
  try {
    return crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
  } catch {
    return null;
  }
}

function pickColumnIndex(headers: string[], keywords: string[]): number {
  for (const kw of keywords) {
    const idx = headers.findIndex(h => h.toLowerCase().includes(kw.toLowerCase()));
    if (idx >= 0) return idx;
  }
  return -1;
}

function parsePlanRows(planMd: string): PlanRow[] {
  const section = getSectionContent(planMd, '测试用例') ?? getSectionContent(planMd, '测试用例清单') ?? '';
  const tables = extractTables(section || planMd);
  const acByTc = new Map(parsePlanTcEntries(planMd).map(e => [e.id, e.acRefs]));
  if (tables.length === 0) return [];
  const t = tables[0];
  const iId = pickColumnIndex(t.headers, ['用例编号', '编号']);
  const iName = pickColumnIndex(t.headers, ['用例名称', '名称']);
  const iPri = pickColumnIndex(t.headers, ['优先级']);
  const iCh = pickColumnIndex(t.headers, ['执行通道', 'execution_channel', 'execution channel']);
  const out: PlanRow[] = [];
  const seen = new Set<string>();
  for (const row of t.rows) {
    const m = (iId >= 0 ? row[iId] : row[0] || '').match(/TC-\d+/i);
    if (!m) continue;
    const id = m[0].toUpperCase();
    if (seen.has(id)) continue;
    seen.add(id);
    out.push({
      id,
      name: (iName >= 0 ? row[iName] : '').trim(),
      priority: (iPri >= 0 ? row[iPri] : '').trim().toUpperCase() || 'P2',
      channelRaw: (iCh >= 0 ? row[iCh] : '').trim(),
      acRefs: acByTc.get(id) ?? [],
    });
  }
  return out;
}

function cell(v: string): string {
  return v.replace(/\|/g, '\\|').replace(/\r?\n/g, ' ');
}

function ms(v: number | null | undefined): string {
  return typeof v === 'number' && Number.isFinite(v) ? `${Math.round(v)}ms` : '—';
}

function firstFailedStepSummary(tc: HylyreTraceCase): string {
  const steps = Array.isArray(tc.steps) ? tc.steps : [];
  for (const step of steps) {
    const s = step as unknown as {
      index?: number; kind?: string; outcome?: { status?: string; failure?: { domain?: string; code?: string; message?: string } };
      diagnostic?: string | null;
    };
    if (!s || s.outcome?.status === 'passed' || s.outcome?.status === undefined) continue;
    const f = s.outcome?.failure;
    const where = `step ${s.index ?? '?'}（${s.kind ?? '?'}）`;
    const cause = f ? `${f.domain ?? '?'}/${f.code ?? '?'}${f.message ? `：${f.message}` : ''}` : `outcome=${s.outcome?.status}`;
    return `${where} ${cause}${s.diagnostic ? `；${s.diagnostic}` : ''}`;
  }
  return typeof tc.notes === 'string' && tc.notes.trim() ? tc.notes.trim() : '无 StepResult 级失败详情（见 trace）';
}

function severityFor(priority: string): DefectRow['severity'] {
  if (priority === 'P0') return 'BLOCKER';
  if (priority === 'P1') return 'MAJOR';
  return 'MINOR';
}

interface VisualFacts {
  available: boolean;
  /** 授权过滤后的有效视图（与 visual_diff 门禁同一来源）；`minor` = 有效处置为 minor 的披露屏。 */
  screens: Array<{ screen_id: string; verdict: string; defects: number; must_fix: number; note: string; minor: boolean; reviewed: boolean }>;
  measure: Map<string, { geometry: AxisStatus; detail: string }>;
}

/**
 * 回执结构合法（门禁同一判据）时返回其 image_inputs 声明的截图 hash 集合；规范路径
 * `device-testing/reports/critic-receipt.json`（visual-provider-review 写入、门禁读取的同一路径）。
 */
function criticReceiptImageHashes(projectRoot: string, feature: string): Set<string> {
  const raw = readJson<Record<string, unknown>>(path.join(featureDir(projectRoot, feature), 'device-testing', 'reports', 'critic-receipt.json'));
  if (!raw || typeof raw !== 'object' || criticReceiptShapeError(raw)) return new Set();
  return new Set((raw.image_inputs as Array<{ hash?: unknown }>)
    .map(i => (typeof i.hash === 'string' ? i.hash.trim() : ''))
    .filter(h => h.length > 0));
}

function collectVisualFacts(projectRoot: string, feature: string): VisualFacts {
  const dir = path.join(featureDir(projectRoot, feature), 'device-testing', 'device-screenshots');
  const out: VisualFacts = { available: false, screens: [], measure: new Map() };
  const raw = readJson<unknown>(path.join(dir, 'visual-diff.json'));
  if (raw) {
    const validated = validateVisualDiffJson(raw, projectRoot);
    if (validated.report && !validated.fatal) {
      out.available = true;
      // plan a2f7c9e4 §3.5：消费门禁同一有效视图与新鲜度判据，不自行推导第二套结论。
      const view = effectiveScreens(validated.report, loadRepairAuthorityScope(projectRoot, feature));
      const currentBuildFingerprint = resolveCurrentBuildFingerprint(projectRoot, feature);
      const receiptHashes = criticReceiptImageHashes(projectRoot, feature);
      for (const s of view.screens) {
        const defects = s.defects ?? [];
        const firstNote = defects.map(d => String(d?.note ?? '')).find(n => n.trim().length > 0) ?? '';
        const shot = typeof s.screenshot_path === 'string' && s.screenshot_path.trim() ? s.screenshot_path : null;
        const currentHash = shot ? hashScreenshotFile(path.resolve(projectRoot, shot)) : null;
        // 已复核 = 已定稿判定绑定当前截图 hash 与构建指纹，且结构合法的规范路径回执覆盖当前截图 hash。
        const reviewed = !isCaptureMutableVerdict(s.verdict) && !isMissingEvaluatedScreenshotHash(s) && currentHash !== null &&
          !isStaleVisualDiffVerdict(s, projectRoot, { currentBuildFingerprint }) && receiptHashes.has(currentHash);
        out.screens.push({
          screen_id: String(s.screen_id ?? ''),
          verdict: String(s.verdict ?? ''),
          defects: defects.length,
          must_fix: (s.must_fix ?? []).length,
          note: firstNote,
          minor: s.verdict === 'warn' && visualResidualDisposition(s) === 'minor',
          reviewed,
        });
      }
    }
  }
  try {
    for (const f of fs.existsSync(dir) ? fs.readdirSync(dir) : []) {
      const m = /^measure-(.+)\.json$/.exec(f);
      if (!m) continue;
      const doc = readJson<{ geometry?: { status?: string; detail?: string } }>(path.join(dir, f));
      const status = doc?.geometry?.status === 'PASS' ? 'PASS' : doc?.geometry?.status === 'FAIL' ? 'FAIL' : 'UNKNOWN';
      out.measure.set(m[1], { geometry: status, detail: doc?.geometry?.detail ?? '' });
    }
  } catch {
    /* 量测文件缺席即 UNKNOWN */
  }
  return out;
}

interface StabilityFacts {
  available: boolean;
  rows: Array<{ tc_id: string; rounds: number; consistent: number; first_divergent_step: number | null }>;
  consistent_all: boolean;
  /** codex review：每条用例同键轮数 ≥2 才有稳定性结论；单轮只是一次执行 */
  min_rounds_met: boolean;
}

function readStability(reportsDir: string): StabilityFacts {
  const doc = readJson<{ rows?: Array<{ tc_id?: string; rounds?: number; consistent?: number; first_divergent_step?: number | null }> }>(
    path.join(reportsDir, 'stability.json'),
  );
  if (!doc || !Array.isArray(doc.rows)) return { available: false, rows: [], consistent_all: false, min_rounds_met: false };
  const rows = doc.rows.map(r => ({
    tc_id: String(r.tc_id ?? ''),
    rounds: Number(r.rounds ?? 0),
    consistent: Number(r.consistent ?? 0),
    first_divergent_step: typeof r.first_divergent_step === 'number' ? r.first_divergent_step : null,
  }));
  return {
    available: true,
    rows,
    consistent_all: rows.every(r => r.rounds > 0 && r.consistent === r.rounds),
    min_rounds_met: rows.length > 0 && rows.every(r => r.rounds >= 2),
  };
}

function pct(n: number, d: number): string {
  if (d === 0) return '—';
  return `${Math.round((n / d) * 1000) / 10}%`;
}

/** 生成整份报告（纯计算，不写盘）。 */
export function generateTestReport(input: TestReportWriterInput): GeneratedTestReport {
  const { projectRoot, feature, reportsDir } = input;
  const trace: HylyreTrace | null = input.tracePath && fs.existsSync(input.tracePath) ? parseHylyreTrace(input.tracePath) : null;
  const timing = readJson<DeviceTestTimingDocument>(path.join(reportsDir, 'device-test-timing.json'));
  const runMeta = readJson<Record<string, unknown>>(path.join(reportsDir, 'device-test-run.meta.json'));
  const buildResult = readJson<Record<string, unknown>>(path.join(reportsDir, 'device-test-build.result.json'));
  const acceptance = loadAcceptanceFlowsDoc(projectRoot, feature);
  const visual = collectVisualFacts(projectRoot, feature);
  const stability = readStability(reportsDir);
  const debtLoad = loadVisualDebtEx(projectRoot, feature);
  const debt = countBlockingDebt(debtLoad.state === 'valid' ? debtLoad.doc : null);
  const debtCorrupt = debtLoad.state === 'invalid';

  const planRows = parsePlanRows(input.planMd);
  const decl = input.channelDecl;
  const gapByTc = new Map(decl.unsupported_gap.map(g => [g.tc_id.toUpperCase(), g]));
  const invalidByTc = new Map(decl.invalid_test.map(g => [g.tc_id.toUpperCase(), g]));
  const hylyreSet = new Set(decl.hylyre_tc_ids.map(id => id.toUpperCase()));
  const visualSet = new Set(decl.visual_tc_ids.map(id => id.toUpperCase()));
  const channelBindingByTc = new Map(
    (input.channelEvidenceBindings ?? []).map(binding => [binding.tc_id.toUpperCase(), binding] as const),
  );
  const traceByTc = new Map((trace?.cases ?? []).map(c => [c.id.toUpperCase(), c]));
  const timingByTc = new Map((timing?.cases ?? []).map(c => [c.id.toUpperCase(), c]));
  const command = typeof runMeta?.command === 'string' ? runMeta.command : '';
  const weakeningFlags = ['--skip-assert-expected'].filter(f => command.includes(f));

  // AC → checkpoint screens（visual 通道 TC 与视觉缺陷的关联用例）
  const screensByAc = new Map<string, string[]>();
  for (const ac of acceptance?.criteria ?? []) {
    const cp = ac.checkpoint;
    const screens = [cp?.pre_screen, cp?.post_screen].filter((s): s is string => typeof s === 'string' && s.trim().length > 0);
    if (screens.length > 0) screensByAc.set(ac.id.toUpperCase(), screens);
  }
  const exec: ExecRow[] = [];
  for (const row of planRows) {
    const gap = gapByTc.get(row.id);
    if (gap) {
      exec.push({ ...row, status: '跳过', duration: '—', note: `unsupported_gap:${gap.reason}（留分母、不算通过）`, source: 'gap' });
      continue;
    }
    if (invalidByTc.has(row.id)) {
      exec.push({ ...row, status: '阻塞', duration: '—', note: `invalid_test：${invalidByTc.get(row.id)!.why}`, source: 'invalid' });
      continue;
    }
    if (visualSet.has(row.id)) {
      const binding = channelBindingByTc.get(row.id);
      // plan c3f8a2d7 §3.2④：capability 归属的视觉绑定 = 能力缺席导致未验证。执行状态取值域只有四个
      // （execution_result_table 门禁），故落「跳过」并在备注写明，留分母、不算通过也不列为待修产品缺陷。
      if (binding && binding.verdict.kind !== 'covered' && binding.repair_owner === 'capability') {
        exec.push({ ...row, status: '跳过', duration: '—', note: `未验证（能力缺席）：${binding.verdict.detail}`, source: 'capability' });
        continue;
      }
      const status: RowStatus =
        binding?.verdict.kind === 'covered' ? '通过'
          : binding?.verdict.kind === 'failed' ? '失败' : '阻塞';
      exec.push({
        ...row, status, duration: '—',
        note: `visual 通道：${binding?.verdict.detail ?? '缺逐 TC 机器裁决'}`,
        source: 'visual',
      });
      continue;
    }
    const tc = traceByTc.get(row.id);
    if (hylyreSet.has(row.id) || decl.hylyre_tc_ids.length === 0) {
      if (tc) {
        const t = timingByTc.get(row.id);
        const status = (['通过', '失败', '阻塞', '跳过'].includes(tc.status) ? tc.status : '阻塞') as RowStatus;
        const note = status === '失败' || status === '阻塞' ? firstFailedStepSummary(tc) : '';
        // plan 5e1c7a93 D3：timing 整行缺席、或该行没量到（duration_ms=null）→ 写 `—`
        // （与同函数 :329/:333 的既有空值占位同款），**不再把"没量到"写成假的 `0ms`**；
        // timing 行在场且值为 0 仍照写 `0ms`（skip case 的正确 0）。
        const durationCell = t && t.duration_ms !== null ? ms(t.duration_ms) : '—';
        exec.push({ ...row, status, duration: durationCell, note, source: 'hylyre' });
      } else {
        exec.push({ ...row, status: '跳过', duration: '—', note: trace ? '未进入本轮权威 trace（explicit skip 或未派生）' : '本轮无权威 trace', source: 'absent' });
      }
      continue;
    }
    exec.push({ ...row, status: '阻塞', duration: '—', note: `通道 ${row.channelRaw || '(空)'} 无执行事实`, source: 'invalid' });
  }

  // 缺陷
  const defects: DefectRow[] = [];
  let n = 0;
  for (const r of exec) {
    if ((r.source === 'hylyre' || r.source === 'visual') && (r.status === '失败' || r.status === '阻塞')) {
      n += 1;
      defects.push({ id: `DEF-${String(n).padStart(3, '0')}`, cases: r.id, severity: severityFor(r.priority), description: `${r.status}：${r.note}`, status: '待修复' });
    }
  }
  const tcByScreen = new Map<string, string[]>();
  for (const row of planRows) {
    for (const ac of row.acRefs) {
      for (const s of screensByAc.get(ac.toUpperCase()) ?? []) tcByScreen.set(s, [...(tcByScreen.get(s) ?? []), row.id]);
    }
  }
  let vn = 0;
  for (const s of visual.screens) {
    if (s.verdict !== 'fail' && s.verdict !== 'warn') continue;
    vn += 1;
    const related = [...new Set(tcByScreen.get(s.screen_id) ?? [])];
    defects.push({
      id: `DEF-V${String(vn).padStart(3, '0')}`,
      cases: related.join(', '),
      severity: s.verdict === 'fail' ? 'MAJOR' : 'MINOR',
      description: `视觉 ${s.verdict}：屏 ${s.screen_id}，defects=${s.defects}，must_fix=${s.must_fix}${s.note ? `；${s.note}` : ''}`,
      // minor 残差只披露、不返修（与门禁有效视图同口径）
      status: s.minor ? '披露' : '待修复',
    });
  }

  // 通过率
  const priorities = [...new Set(exec.map(r => r.priority))].sort();
  const thresholds: Record<string, number | null> = { P0: 100, P1: 95 };
  const rateRows: string[] = [];
  const rateOf = (rows: ExecRow[]) => {
    const total = rows.length;
    const pass = rows.filter(r => r.status === '通过').length;
    const fail = rows.filter(r => r.status === '失败').length;
    const blocked = rows.filter(r => r.status === '阻塞').length;
    const skipped = rows.filter(r => r.status === '跳过').length;
    const gaps = rows.filter(r => r.source === 'gap').length;
    return { total, pass, fail, blocked, skipped, gaps, ratio: total === 0 ? 0 : (pass / total) * 100 };
  };
  const priorityStats = new Map<string, ReturnType<typeof rateOf>>();
  for (const p of priorities) {
    const st = rateOf(exec.filter(r => r.priority === p));
    priorityStats.set(p, st);
    const th = thresholds[p] ?? null;
    const ok = th === null ? '—' : st.ratio >= th ? '✅' : '❌';
    rateRows.push(`| ${p} | ${st.total} | ${st.pass} | ${st.fail} | ${st.blocked} | ${st.skipped}${st.gaps > 0 ? `（含 gap ${st.gaps}）` : ''} | ${pct(st.pass, st.total)} | ${th === null ? '—' : p === 'P0' ? '100%' : `≥ ${th}%`} | ${ok} |`);
  }
  const all = rateOf(exec);
  rateRows.push(`| **总计** | **${all.total}** | **${all.pass}** | **${all.fail}** | **${all.blocked}** | **${all.skipped}${all.gaps > 0 ? `（含 gap ${all.gaps}）` : ''}** | **${pct(all.pass, all.total)}** | **≥ 90%** | **${all.ratio >= 90 ? '✅' : '❌'}** |`);

  // 轴
  const hylyreRows = exec.filter(r => r.source === 'hylyre');
  const functional: AxisStatus =
    !trace ? 'UNKNOWN'
      : hylyreRows.some(r => r.status === '失败' || r.status === '阻塞') ||
          exec.some(r => r.source === 'absent' && hylyreSet.has(r.id)) ||
          exec.some(r => r.priority.toUpperCase() === 'P0' && r.source !== 'gap' && r.source !== 'capability' && r.status !== '通过') ||
          trace.outcome !== 'success'
        ? 'FAIL'
        : 'PASS';
  const stabilityAxis: AxisStatus = !stability.available || !stability.min_rounds_met ? 'UNKNOWN' : stability.consistent_all ? 'PASS' : 'FAIL';
  const p0Screens = new Set(
    resolveP0DeviceObligations(projectRoot, feature, acceptance).checkpoints.flatMap(ac => screensByAc.get(ac.id.toUpperCase()) ?? []),
  );
  const canonicalP0Targets = new Set(collectP0VisualTargetIds(loadUiSpecFile(uiSpecAbsPath(projectRoot, feature))));
  // 视觉轴只在 feature 确有视觉面（有 visual-diff.json 或 P0 checkpoint 屏）时才计入缺口
  const visualApplicable = visual.available || p0Screens.size > 0;
  let visualGeometry: AxisStatus = visualApplicable ? 'UNKNOWN' : 'NOT_APPLICABLE';
  const relevantScreens = visual.screens.filter(s =>
    canonicalP0Targets.size > 0 ? canonicalP0Targets.has(s.screen_id) : p0Screens.size === 0 || p0Screens.has(s.screen_id));
  if (!visualApplicable) {
    /* 无视觉面：三轴 NOT_APPLICABLE，不进缺口 */
  } else if (visual.measure.size > 0) {
    const statuses = [...visual.measure.values()].map(m => m.geometry);
    visualGeometry = statuses.some(s => s === 'FAIL') ? 'FAIL' : statuses.every(s => s === 'PASS') ? 'PASS' : 'UNKNOWN';
  } else if (visual.available && visual.screens.length > 0) {
    // minor 披露屏已评估（WARN 披露），不再因不是 raw pass 而记 UNKNOWN
    visualGeometry = relevantScreens.some(s => s.verdict === 'fail') ? 'FAIL'
      : relevantScreens.length > 0 && relevantScreens.every(s => s.verdict === 'pass' || s.minor) ? 'PASS' : 'UNKNOWN';
  }
  const contentReviewed = relevantScreens.length > 0 && relevantScreens.every(s => s.reviewed);
  const visualContent: CheckStatus = !visualApplicable ? 'NOT_APPLICABLE' : contentReviewed ? 'CHECKED' : 'UNKNOWN';
  const visualStyle: CheckStatus = !visualApplicable ? 'NOT_APPLICABLE' : contentReviewed ? 'CHECKED' : 'UNKNOWN';
  // 显式断言（role=assertion）与被弱化旗标跳过的自然语言预期分别计数；旗标只限定被跳过的部分。
  const assertionSteps = (trace?.cases ?? []).flatMap(c => (Array.isArray(c.steps) ? c.steps : []))
    .filter(st => st?.role === 'assertion');
  const assertionsPassed = assertionSteps.filter(st => st.outcome?.status === 'passed').length;
  const assertionsSkipped = assertionSteps.filter(st => st.outcome?.status === 'skipped').length;
  const assertionText = `显式断言 ${assertionsPassed}/${assertionSteps.length - assertionsSkipped} 通过，自然语言预期跳过 ${assertionsSkipped} 条`;

  const gaps: string[] = [];
  for (const g of decl.unsupported_gap) gaps.push(`${g.tc_id}[${g.channel}:${g.reason}]`);
  if (debt.open + debt.accepted > 0) gaps.push(`视觉债务 open=${debt.open}, accepted=${debt.accepted}（visual-debt.md）`);
  if (debtCorrupt) gaps.push('视觉债务账本损坏（visual-debt.json 不可解析）');
  if (visualGeometry === 'FAIL' || visualGeometry === 'UNKNOWN') gaps.push(`视觉几何 ${visualGeometry}`);
  if (visualContent === 'UNKNOWN') gaps.push('视觉内容/样式 UNKNOWN（无绑定当前截图与构建的 provider 复核）');
  if (stabilityAxis === 'UNKNOWN') gaps.push(stability.available ? '交互稳定性 UNKNOWN（同执行键真实执行不足 2 轮，单轮不构成稳定性证据）' : '交互稳定性 UNKNOWN（无 stability.json）');
  // 弱化旗标在场时结论恒不签「达标」（与 check-testing 的弱化旗标门禁同口径）；措辞只限定实际跳过的部分。
  for (const f of weakeningFlags) {
    gaps.push(assertionSteps.length === 0
      ? `弱化旗标 ${f}：trace 无结构化断言步骤，「通过」仅为动作链执行完成，非验收通过`
      : `弱化旗标 ${f}：自然语言预期跳过 ${assertionsSkipped} 条（未验证）；显式断言 ${assertionsPassed} 条通过；结论不以「达标」签发`);
  }
  // 视觉总体结论取 testing gate 本轮视觉检查的结论，不由报告自行推导（soft 档只记债务、门禁不阻断）。
  // plan c3f8a2d7 §3.2④：能力缺席投影（externalBlocked/capability_missing）只进缺口、不判 FAILED；其余视觉阻断照旧。
  const blockingVisual = (input.visualChecks ?? []).filter(check => isBlockingCheck(check));
  const visualAbsent = blockingVisual.filter(isCapabilityAbsenceCheck);
  const visualBlockers = blockingVisual.filter(check => !isCapabilityAbsenceCheck(check));
  const absentScope = [...visualAbsent.map(c => c.id), ...exec.filter(r => r.source === 'capability').map(r => r.id)];
  if (absentScope.length > 0) gaps.push(`视觉轴能力缺席（视觉 provider 不可用或 OCR 执行能力缺失）：暂缓，非产品失败（${absentScope.join('、')}）`);
  if (visualBlockers.length > 0) gaps.push(`视觉门禁阻断（${visualBlockers.map(c => `${c.id} ${c.status}/${c.severity ?? '-'}`).join('、')}）`);

  const overall: OverallStatus = functional === 'FAIL' || visualBlockers.length > 0 ? 'FAILED' : gaps.length > 0 || functional === 'UNKNOWN' ? 'COMPLETE_WITH_GAPS' : 'COMPLETE';
  const declared: TestReportConclusion['declared_verdict'] =
    overall === 'FAILED' ? '不达标' : overall === 'COMPLETE_WITH_GAPS' ? '有条件达标' : '达标';

  const conclusion: TestReportConclusion = {
    functional, stability: stabilityAxis, visual_geometry: visualGeometry, visual_content: visualContent,
    visual_style: visualStyle, gaps, overall, declared_verdict: declared,
  };

  // 渲染
  const rel = (p: string | null): string => (p ? path.relative(projectRoot, p).replace(/\\/g, '/') : '—');
  const traceSha = input.tracePath ? sha256File(input.tracePath) : null;
  const env = trace?.environment as Record<string, unknown> | undefined;
  const envText = [
    typeof runMeta?.device_serial === 'string' ? `device ${runMeta.device_serial}` : null,
    typeof runMeta?.device === 'string' ? `device ${runMeta.device}` : null,
    env && typeof env.hylyre_version === 'string' ? `hylyre ${env.hylyre_version}` : null,
    env && typeof env.hypium_version === 'string' ? `hypium ${env.hypium_version}` : null,
  ].filter((v): v is string => Boolean(v)).join(', ') || '（见 device-test-run.meta.json）';
  const buildAt = typeof buildResult?.timestamp === 'string' ? buildResult.timestamp.trim() : '';
  const pipeline = timing?.pipeline;
  // codex review（plan 07a41ec6 T7）：报告正文不写当前时间（否则每次重生成都换 verifier subject）——用权威 run 时间。
  const dateText =
    (typeof runMeta?.run_started_at === 'string' && runMeta.run_started_at.trim()) ||
    (typeof runMeta?.ran_at === 'string' && runMeta.ran_at.trim()) ||
    (typeof timing?.generated_at === 'string' && timing.generated_at.trim()) ||
    '（无权威 run 时间）';

  const lines: string[] = [];
  lines.push(
    TEST_REPORT_GENERATED_MARKER,
    `# 测试报告 — ${feature}`,
    '',
    `> **模块标识**: \`${feature}\``,
    `> **版本**: harness-generated ${dateText}`,
    `> **日期**: ${dateText}`,
    '> **测试执行人**: harness（机器生成；agent 观察见 testing/notes.md）',
    `> **对应测试计划**: \`${rel(resolveFeatureArtifact(projectRoot, feature, 'test-plan.md').actualPath)}\``,
    `> **权威 run**: \`${rel(input.tracePath)}\`${traceSha ? `（trace sha256 ${traceSha.slice(0, 16)}）` : ''}`,
    '',
    '> 本文件由 harness 从 trace / timing / meta / gaps / visual-diff / visual-debt / measure / stability 整份生成，重跑 harness 或 `--report-reconcile-only` 会重写；请勿手改，观察与决策写 `testing/notes.md`。',
    '',
    '---',
    '',
    '## 一、测试概览',
    '',
    '| 项目 | 内容 |',
    '|------|------|',
    `| 测试模块 | ${feature} |`,
    `| 测试日期 | ${dateText} |`,
    `| 测试环境 | ${cell(envText)} |`,
    '| 执行人 | harness（机器生成） |',
    `| 用例总数 | ${exec.length} |`,
    `| 执行用例数 | ${exec.filter(r => r.source === 'hylyre').length} |`,
    `| 跳过用例数 | ${exec.filter(r => r.status === '跳过').length} |`,
    '',
    '### 真机流水线耗时',
    '',
    '> 数据来源：device-test-timing.json（harness 在 device_test.run 成功后写入）；耗时为精确整数毫秒，`—` 表示无数据。',
    '',
    '| 阶段 | 耗时 | 说明 |',
    '|------|------|------|',
    `| 打包 (hvigor) | ${ms(pipeline?.build_ms)} | ${pipeline?.build_reused ? '复用既有 HAP' : '本轮构建'}; \`reused=${pipeline ? String(pipeline.build_reused) : 'false'}\` |`,
    `| 装机 (hdc) | ${ms(pipeline?.install_ms)} | ${pipeline?.install_reused ? '复用已装版本' : '本轮安装'}; \`reused=${pipeline ? String(pipeline.install_reused) : 'false'}\` |`,
    `| Hylyre 自动化 | ${ms(pipeline?.hylyre_run_ms)} | 含设备预启动 |`,
    `| 快照写入 (page save) | ${ms(pipeline?.page_save_ms)} | 非致命 |`,
    `| **合计（脚本统计）** | **${ms(pipeline?.total_harness_ms)}** | harness 各阶段之和（writer 为 null 时为 —） |`,
    '',
    '| 元数据 | 值 |',
    '|--------|-----|',
    `| HAP 落盘时间 (hapBuiltAt) | ${pipeline?.hap_built_at ?? '—'} |`,
    `| 本次 harness 跑 build 门禁时刻 | ${buildAt || '—'} |`,
    '',
    '---',
    '',
    '## 二、测试执行结果',
    '',
    '| 用例编号 | 用例名称 | 优先级 | 执行状态 | 耗时 | 备注 |',
    '|----------|---------|--------|---------|------|------|',
    ...exec.map(r => `| ${r.id} | ${cell(r.name)} | ${r.priority} | ${r.status} | ${r.duration} | ${cell(r.note)} |`),
    '',
  );
  if (assertionSteps.length > 0) {
    lines.push(`> **断言披露**：${assertionText}。`, '');
  }
  if (weakeningFlags.length > 0) {
    lines.push(
      assertionSteps.length === 0
        ? `> **弱化旗标披露**：本轮真机执行命令含 ${weakeningFlags.join('、')}——表中「通过」仅表示动作链执行完成，未验证自然语言预期/性能/视觉断言，非验收通过。`
        : `> **弱化旗标披露**：本轮真机执行命令含 ${weakeningFlags.join('、')}——只跳过上述 ${assertionsSkipped} 条自然语言预期（这部分未验证、非验收通过）；显式断言照常执行并按结果计入。`,
      '',
    );
  }
  lines.push(
    '### 稳定性（同执行键跨轮）',
    '',
  );
  if (stability.available && stability.rows.length > 0) {
    lines.push(
      '| 用例编号 | 同键轮数 | 一致轮数 | 首个分歧 step |',
      '|----------|---------|---------|--------------|',
      ...stability.rows.map(r => `| ${r.tc_id} | ${r.rounds} | ${r.consistent} | ${r.first_divergent_step ?? '—'} |`),
      '',
    );
  } else {
    lines.push('> 未生成（无 stability.json；需要 ≥2 轮同执行键的真实执行才有稳定性证据）。', '');
  }
  lines.push('---', '', '## 三、缺陷清单', '');
  if (defects.length === 0) {
    lines.push('无缺陷：所有已执行用例全部通过，视觉屏无 fail/warn。', '');
  } else {
    lines.push(
      '| 缺陷编号 | 关联用例 | 严重程度 | 描述 | 状态 |',
      '|----------|---------|---------|------|------|',
      ...defects.map(d => `| ${d.id} | ${d.cases} | ${d.severity} | ${cell(d.description)} | ${d.status} |`),
      '',
    );
  }
  const sevCount = (sev: DefectRow['severity']) => defects.filter(d => d.severity === sev).length;
  const toFix = (sev?: DefectRow['severity']) => defects.filter(d => d.status === '待修复' && (!sev || d.severity === sev)).length;
  lines.push(
    '### 缺陷统计',
    '',
    '| 严重程度 | 数量 | 待修复 | 已修复 | 已关闭 | 延期处理 |',
    '|---------|------|--------|--------|--------|---------|',
    `| BLOCKER | ${sevCount('BLOCKER')} | ${toFix('BLOCKER')} | 0 | 0 | 0 |`,
    `| MAJOR | ${sevCount('MAJOR')} | ${toFix('MAJOR')} | 0 | 0 | 0 |`,
    `| MINOR | ${sevCount('MINOR')} | ${toFix('MINOR')} | 0 | 0 | 0 |`,
    `| **合计** | **${defects.length}** | **${toFix()}** | **0** | **0** | **0** |`,
    '',
    '---',
    '',
    '## 四、通过率统计',
    '',
    '| 优先级 | 总用例 | 通过 | 失败 | 阻塞 | 跳过 | 通过率 | 达标阈值 | 是否达标 |',
    '|--------|--------|------|------|------|------|--------|---------|---------|',
    ...rateRows,
    '',
    '> 通过率 = 通过 / 总用例；unsupported_gap 留在总用例分母、不计入通过（P0 五数口径见 summary.json p0_coverage_integrity.structured）。',
    '',
    '---',
    '',
    '## 五、结论',
    '',
    `**测试结论**: ${declared}`,
    '',
    '**按轴结论**（确定性派生）:',
    `- 功能：${functional}（hylyre ${hylyreRows.filter(r => r.status === '通过').length}/${hylyreRows.length} 通过，失败 ${hylyreRows.filter(r => r.status === '失败').length}，阻塞 ${hylyreRows.filter(r => r.status === '阻塞').length}${trace ? `，trace.outcome=${trace.outcome}` : '，无权威 trace'}${assertionSteps.length > 0 ? `；${assertionText}` : ''}）`,
    `- 交互稳定性：${stabilityAxis}${stability.available ? `（${stability.rows.length} 条用例有同键多轮数据）` : '（无 stability.json）'}`,
    `- 视觉几何：${visualGeometry}${visual.measure.size > 0 ? `（measure 文件 ${visual.measure.size} 屏）` : visual.available ? `（visual-diff.json ${visual.screens.length} 屏：${visual.screens.map(s => `${s.screen_id}=${s.verdict}`).join('、')}）` : '（无 visual-diff.json）'}`,
    `- 视觉内容：${visualContent}`,
    `- 视觉样式：${visualStyle}`,
    `- 已知缺口：${gaps.length === 0 ? '无' : `${gaps.length} 项`}`,
    ...gaps.map(g => `  - ${g}`),
    `- 总体：${overall}`,
    '',
    '**判定依据**:',
    ...priorities.map(p => {
      const st = priorityStats.get(p)!;
      const th = thresholds[p] ?? null;
      return `- ${p} 通过率: ${pct(st.pass, st.total)}（${th === null ? '无阈值' : p === 'P0' ? '阈值 100%' : `阈值 ≥ ${th}%`}）`;
    }),
    `- 总体通过率: ${pct(all.pass, all.total)}（阈值 ≥ 90%）`,
    `- BLOCKER 缺陷: ${sevCount('BLOCKER')} 个`,
    debt.open + debt.accepted > 0
      ? `- 视觉债务 ${debt.open + debt.accepted} 条未清偿（open=${debt.open}, accepted=${debt.accepted}；SSOT=visual-debt.json / summary.quality_axes），功能达标与视觉验真是两根轴`
      : '- 视觉债务 0 条',
    '',
    '**下一步建议**:',
    overall === 'FAILED'
      ? '- 修复失败/阻塞用例（见缺陷清单）后重跑 testing harness；未执行的 hylyre 用例补跑。'
      : overall === 'COMPLETE_WITH_GAPS' && absentScope.length > 0
        ? '- 视觉轴能力缺席（视觉 provider 不可用或 OCR 执行能力缺失）：恢复缺席的视觉能力（provider / OCR）后重新发起同一请求，由同一检查重验；暂缓项不是待修产品缺陷，release_readiness 保持阻断。'
      : overall === 'COMPLETE_WITH_GAPS'
        ? '- 功能完成可推进；已知缺口按条目在需求/spec 登记并披露，视觉缺口不阻止功能完成但阻断 release_readiness。'
        : '- 功能模块验收完成。',
    '',
  );
  return { content: lines.join('\n'), conclusion, trace_path: input.tracePath };
}

export interface WriteGeneratedTestReportResult {
  written: boolean;
  path: string;
  legacy_moved_to?: string;
  conclusion?: TestReportConclusion;
  reason?: string;
}

/** 写入 canonical test-report.md；首次覆盖手写报告时把旧文件迁到 testing/notes.legacy-report.md 留档。 */
export function writeGeneratedTestReport(input: TestReportWriterInput): WriteGeneratedTestReportResult {
  const target = resolveFeatureArtifact(input.projectRoot, input.feature, 'test-report.md').canonicalPath;
  try {
    const generated = generateTestReport(input);
    let legacyMovedTo: string | undefined;
    if (fs.existsSync(target)) {
      const existing = fs.readFileSync(input.projectRoot ? target : target, 'utf-8');
      if (!existing.includes(TEST_REPORT_GENERATED_MARKER)) {
        const notesDir = path.join(featureDir(input.projectRoot, input.feature), 'testing');
        fs.mkdirSync(notesDir, { recursive: true });
        legacyMovedTo = path.join(notesDir, 'notes.legacy-report.md');
        fs.writeFileSync(legacyMovedTo, `<!-- 由 harness 迁移：以下是机器生成报告接管前的手写 test-report.md（plan 07a41ec6 T5） -->\n\n${existing}`, 'utf-8');
      }
    }
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, generated.content, 'utf-8');
    return { written: true, path: target, ...(legacyMovedTo ? { legacy_moved_to: legacyMovedTo } : {}), conclusion: generated.conclusion };
  } catch (e) {
    return { written: false, path: target, reason: (e as Error).message };
  }
}
